    "summaryZh": "该规则由美国国家档案与文件管理局(NARA)发布，修订《联邦法规》第36编第1220、1222和1228部分，专门对联邦文件存储进行规范。内容涵盖文件存储设施的物理安全、环境控制与防火标准，以及设施向NARA申请批准的程序。规则于2000年1月3日生效，适用于永久性和临时性联邦文件的保管场所，旨在保障文件在保管链中的完整性与可获取性。作为美国联邦文件管理法规体系的核心组成部分，该文件为电子与非电子文件的长期保存提供了操作性规范，对研究美国档案法规、数字保存制度及中外文件管理比较均具重要收录价值。",
