    "summaryZh": "该专题页面由美国国家档案馆（archives.gov）维护，作为其战略规划文件的核心入口。页面当前首要展示正在起草的《2026-2030 财政年度战略规划框架》（PDF），该框架明确了NARA的使命、愿景、价值观和高层目标，为后续完整计划的制定奠定基础。同时，页面汇集了自2000年以来多份已发布的历史战略计划，涵盖2022-2026、2018-2022、2014-2018、2009、2006等版本，并提供PDF及部分HTML格式下载。所有PDF文件均需Adobe Reader阅读，并附有无障碍访问说明。该资源为研究美国联邦档案机构的中长期战略演变、公共服务定位、数字资源保存和开放获取承诺提供了系统化的文档集。",
