    "summaryZh": "该资料为美国国家档案馆（NARA）发布的“通用文件处置表”指导页面。它系统介绍了 GRS 的性质：由 NARA 为联邦通用文件统一发布处置授权，避免各机构重复申请，主要覆盖行政或支持职能文件，不触及机构核心使命文件。页面强调 GRS 的使用具有强制性，除非机构能合理申请例外；并说明了 GRS 的新增与修订通过《GRS 传送单》发布，以及机构若希望继续沿用原有机构专属处置权时需提交 GRS 通知。此外，页面集成了丰富的操作指南与工具资源，包括处置权查找表、交叉对照表、主题索引和机器可执行的 GRS 清单等，是联邦文件管理人员理解和应用 GRS 的核心入口。对于中文档案学领域，该资源为理解美国联邦文件处置制度、比较中美通用文件保管期限表提供了权威参考。",
