    "summaryZh": "该页面原为NARA官方网站上的电子邮件管理主题入口，旨在指导联邦机构依据《联邦文件法》及相关法规管理电子邮件文件。页面详细列出了《管理政府文件指令》（M-12-18）提出的2016年底前以可访问电子格式管理永久和临时电子邮件的目标，介绍了NARA 2013-2公告确立的“顶石方法”（Capstone Approach）作为替代管理方案，并提供了通用文件处置表GRS 6.1的处置授权。页面汇总了电子邮件具体指南、Capstone培训资源、机构实施样本和联邦机构电子邮件管理实践案例的链接。该页面已被取代，现仅作为历史参考保留，研究者可借此了解NARA在2016年前后推动电子邮件管理的政策框架与技术路径。",
