    "summaryZh": "该资源是美国国家档案馆（NARA）官方网站的“Getting Started Overview”专题入口页面，旨在为初次使用馆藏的公众提供清晰的研究启动指引。页面按四步流程组织：确定研究主题、收集相关信息、查找档案与档案信息、决定是否并如何计划实地到访。同时概述了馆藏特色，说明联邦政府日常活动中仅1%-3%的文件因法律或历史重要性被永久保存，并可从家族历史、退伍军人服役证明、历史课题等角度加以利用。该页面聚合了各步骤的详细指南链接和线上研究工具，是NARA面向公众提供档案利用服务的核心门户之一，对档案学领域的利用者教育、公共服务设计和国际档案资源推广具有参考价值。",
