    "summaryZh": "该页面为美国国家档案馆（NARA）官方网站的公共活动日历栏目，聚合了全国各分支机构即将举行的活动信息，如政府信息服务办公室公开年会、胡佛总统图书馆重新开馆剪彩仪式、美国历史知识竞赛之夜、艾森豪威尔读书俱乐部虚拟圆桌会议、面向K-12教师的专业发展工作坊、音乐会以及多场历史主题讲座。活动形式涵盖线上和线下，地点遍布艾奥瓦州、密歇根州、加利福尼亚州和堪萨斯州等地。作为面向公众的信息入口，该日历展示了NARA在档案教育、公众参与和历史记忆传播方面的多元实践，是研究档案机构社会化服务与社区连结的重要参照。",
