    "summaryShort": "这是美国国家档案与文件管理署（NARA）于2026年7月23日在《联邦公报》上发布的通知，宣布拟续期一项通用信息收集许可，用于收集公众对机构服务交付的定性反馈，并邀请公众在2026年9月21日前提交意见。用户可从中了解美国联邦机构依据《文书削减法》进行信息收集管理的程序及公众参与方式。",
