    "summaryZh": "该资料为NARA于2026年5月8日发布的联邦公报通知，依据《文书削减法》，就称为“附表A与退伍军人招聘倡议”的信息收集提案征求公众意见。NARA拟收集关于利用附表A（残疾人士非竞争性聘用授权）和退伍军人招聘计划的信息，以支持其招聘工作并评估计划有效性。通知说明了提案提交、审批程序以及公众提交意见的方式和截止日期。作为联邦政府负责文件与档案管理的核心机构，NARA自身的业务文件管理同样须遵循法定程序，此通知为研究美国联邦信息收集合规管理与档案行政程序结合提供了实例。",
