    "summaryZh": "该通知由美国国家档案与文件署（NARA）发布，正式宣布国会文件咨询委员会（Advisory Committee on the Records of Congress）将于2025年12月10日和11日召开两次虚拟公开会议，每次会议对公众开放30分钟。通知明确了会议时间（东部时间）、注册链接、联系方式等基本信息，并简要说明会议将围绕委员会向国会提交的报告及其他行政事务展开讨论。作为一项正式的联邦公报通知，它体现了美国档案管理机构在咨询委员会运作中的程序透明要求，同时也为研究美国国会文件与文件管理机制、公众参与渠道以及NARA的顾问机构治理提供了直接的一手文件。",
