    "resourceId": "fr-2024-11915",
    "titleZh": "联邦文件管理：GAO 同意程序更正",
    "summaryShort": "该文件是美国国家档案与文件署（NARA）在《联邦公报》上发布的一项规则更正，针对2024年5月1日生效的《联邦文件管理：GAO同意》直接最终规则中的错误进行修正，确保涉及联邦文件处置前须获得美国政府问责局（GAO）同意的程序规定准确无误。",
    "summaryZh": "2024年6月3日，美国国家档案与文件署（NARA）在《联邦公报》上发布第2024-11915号文件，标题为《联邦文件管理：GAO 同意；更正》。该文件是对此前于2024年5月1日发布的《联邦文件管理：GAO同意》直接最终规则（文件号2024-09396）进行修正的更正规则。原始规则涉及联邦机构在销毁或处置联邦文件之前须获得美国政府问责局（GAO）同意的程序，被收录于《联邦法规》第36编第1225部分。本次更正旨在消除原始规则文本中的错误，以确保法规条款的准确性和可执行性。更正规则于2024年7月30日正式生效。对档案学研究者与从业者而言，该资料提供了研究美国联邦文件管理制度、规则修订及更正机制的具体案例，有助于理解NARA与GAO在文件处置审批中的权责关系。",
    "keyPoints": [
      "该文件是 NARA 发布的正式规则更正（Direct final rule; correction），对美国现行联邦文件管理法规进行修正。",
      "更正对象为2024年5月1日发布的《联邦文件管理：GAO同意》直接最终规则（文件号 2024-09396），涉及联邦文件处置须获得GAO同意的程序。",
      "修正内容纳入《联邦法规》第36编第1225部分（36 CFR part 1225），确保联邦机构在销毁或移交文件前审批流程的准确性。",
      "该更正规则于2024年7月30日生效，用于消除前序规则文本中的错误，不改变实质性的文件处置审批要求。",
      "该资料在《联邦公报》上发布，并附有RIN号3095-AC12及相关案卷号NARA-24-0008和NARA-2024-026。"
    ],
    "researchValue": "该资料可用于研究美国联邦文件管理法规的修订与纠正机制、NARA与GAO在联邦文件处置审批中的权责划分，以及《联邦法规》第36编第1225部分的具体规定。对档案学研究者、比较文件管理制度的学习者以及中国档案从业者了解美国文件管理法律框架中的程序性细节和规则发布流程具有参考价值。",
