    "resourceId": "fr-2023-21867",
    "titleZh": "机构信息收集活动：拟议信息收集；征求评论；机构服务交付定性反馈通用许可",
    "summaryShort": "美国国家档案与文件管理局（NARA）在《联邦公报》发布通知，征求对一项通用信息收集许可的公众评论。该许可旨在系统性地收集关于机构服务交付的定性反馈，例如通过焦点小组、客户调查等方式，以改善用户体验。",
    "summaryZh": "2023年10月3日，NARA根据《减少文书工作法》发布通知，拟向管理和预算办公室（OMB）申请为期三年的通用信息收集许可，专门用于收集公众对NARA服务交付的定性反馈。收集方法包括简短调查、焦点小组、深度访谈等，旨在快速获取用户意见以提升服务质量。该通知邀请公众在2023年11月2日前就信息收集的必要性、实用性、负担估计等方面提交评论。对于档案学界和从业者而言，该文档是了解美国档案机构如何通过制度化的信息收集改善公共服务、落实用户参与机制的重要案例。",
    "keyPoints": [
      "NARA 寻求 OMB 批准一项为期三年的通用清除（generic clearance），专门用于定期收集关于其服务交付的定性反馈。",
      "拟议的信息收集工具包括简短调查、焦点小组、一手客户访谈等，旨在快速迭代改进服务。",
      "通知要求公众就信息收集的必要性、对受访者的负担估计、数据用途以及是否有利于机构职能履行等提出评论，截止日期为 2023 年 11 月 2 日。",
      "该通知依据《减少文书工作法》（Paperwork Reduction Act）发布，遵循联邦机构信息收集审批程序。",
      "NARA 承诺仅利用反馈提升项目与服务，不会用于主要影响个人权利义务的监管或决策。"
    ],
    "researchValue": "该资料可用于研究美国联邦档案机构如何依据《减少文书工作法》建立服务反馈机制，探索档案公共服务评估的理论和实践。对于比较不同国家档案机构用户参与模式、信息收集合规性流程，以及将公众定性数据融入档案服务改进路径，均具有参考价值。同时也可作为公共管理领域关于“机构服务交付反馈”信息收集审批流程的实证案例。",
