    "resourceId": "fr-2023-09050",
    "titleZh": "联邦文件管理：永久文件数字化与文件处置期限表审查规则",
    "summaryShort": "美国国家档案与文件署（NARA）发布的最终规则，修订36 CFR第XII章中关于永久文件数字化及文件处置期限表审查的条款，确立了联邦机构在数字化流程、质量控制与处置表提交等方面的合规要求。",
    "summaryZh": "该规则由美国国家档案与文件署（NARA）于2023年5月4日发布，修订了《联邦法规》第36篇第1224、1225和1236部分，旨在规范联邦机构永久文件的数字化实践，并完善文件处置期限表的审查与批准程序。规则就数字化格式、元数据标准、长期保存要求等提出了具体技术与管理规定，同时调整了机构提交处置期限表的时间节点与材料要求。作为美国联邦文件管理法规的重要组成部分，该规则为档案学领域研究电子文件管理政策、数字资源长期保存制度及文件鉴定与处置的法定程序提供了最新的官方依据。",
    "keyPoints": [
      "规则修订了36 CFR 1224、1225和1236，直接涉及永久文件的数字化标准与文件处置期限表的审查流程。",
      "明确了联邦机构对永久文件进行数字化时需遵循的格式、元数据和质量控制要求，以保障数字档案的长期可用性。",
      "更新了文件处置期限表的提交、公告和批准程序，确保处置决定符合法定文件管理原则。",
      "该最终规则于2023年6月5日生效，对所有联邦机构的文件管理实践具有法律约束力。"
    ],
    "researchValue": "该规则可用于深度分析美国联邦文件管理法规在数字化环境下的演进，比较中外电子文件保管与长久保存制度，研究文件处置与鉴定的法律框架，以及探讨数字存档的技术标准与合规性要求，适合从事档案法治、数字资源保存和政府文件管理研究的学者、学生及从业者参考。",
