    "summaryZh": "2026年4月2日，美国国家档案与文件署（NARA）在《联邦公报》上发布通知（文档号2026-06424），就其拟议使用的“同意查询与信息文件发布”（Consent To Make Inquiries and Release of Information and Records）表格征求公众书面意见。该表格将用于获取个人或机构授权，允许NARA进行档案信息查询并公开相关文件，直接关联电子文件管理中的隐私保护与信息访问机制。公众须于2026年5月31日前提交评论，这是NARA按照行政程序要求推进的公众参与步骤。该资料为跟踪美国联邦档案机构在档案利用同意授权、个人信息保护及行政透明度方面的实践提供了直接依据。",
