    "resourceId": "fr-2019-27326",
    "titleZh": "文件管理；通用文件表（GRS）；第30号GRS传递通知",
    "summaryShort": "美国国家档案与文件署（NARA）于2019年12月19日发布的联邦公报通知，正式传达通用文件表（GRS）第30号修订。用户可从中了解联邦机构通用文件处置规则的更新范围与生效时间。",
    "summaryZh": "该资料为《联邦公报》上的官方通知，由美国国家档案与文件署（NARA）发布，正式发布《通用文件表（GRS）第30号传递通知》。该通知对联邦机构通用的文件处置与保管期限表进行了修订，涉及行政管理文件、临时文件、电信文件、信息技术文件以及数据与信息文件等多个序列。修订旨在适应电子文件环境的变化，优化联邦文件管理实践。该通知于2019年12月19日起生效。对于研究美国联邦文件管理制度、通用文件表更新机制以及电子文件处置政策的学者和从业者而言，该资料是跟踪政策演变的重要原始文件。",
    "keyPoints": [
      "该通知正式发布GRS Transmittal 30，对通用文件表（GRS）进行修订。",
      "修订涉及的GRS章节包括GRS 1.1（行政管理文件）、GRS 1.3（大多数办公室通用文件）、GRS 2.1（临时文件）、GRS 2.3（电话和电信文件）、GRS 2.4（信息技术文件）以及GRS 4.1（数据和信息文件）。",
      "通知明确了修订内容自2019年12月19日起对所有联邦机构生效，所有机构必须据此更新其内部文件表。",
      "传达的更改旨在使GRS更好地反映电子文件环境下的管理需求，确保文件处置政策符合现行法律与技术环境。"
    ],
    "researchValue": "该资料可用于研究美国联邦文件管理制度中的通用文件表（GRS）更新程序与内容，尤其关注电子文件处置政策的变化。它有助于进行中美档案处置政策的比较研究，分析电子文件生命周期管理的政策框架，以及探讨联邦机构合规管理的实践。对于档案学学习者和研究者，它提供了制度更新的原始证据。",
