    "summaryZh": "该联邦公报通知由NARA于2015年2月6日发布，依据《总统文件法》授权，宣布计划处置保存在布什和克林顿总统图书馆的特定录音磁带等原始档案。这些磁带已完成修复并迁移至数字格式，NARA拟在核实后销毁原件以节约存储空间。通知介绍了处置对象详情、修复项目及保留的文件，并邀请公众在2015年3月23日前提交意见。文件反映了美国联邦总统档案处置的法定程序、透明性要求和数字保存实践，为研究档案处置政策、数字迁移策略及公众监督机制提供了具体案例。",
