    "summaryZh": "该通知为NARA在《联邦公报》上发布的通用文件处置表（GRS）第28号传送，旨在更新联邦机构通用的文件处置授权。主要变更包括：修改GRS 1.1（文件识别与描述数据）以反映现代文件管理需求；删除GRS 4.3（财务文件相关）以避免重复规定；并说明新GRS项目的引用方式、机构实施要求和获取途径。对于档案学领域，它展示了美国联邦层面文件处置表的动态维护机制，体现了电子文件环境下处置政策的适应性调整，为研究文件生命周期管理、保留与销毁政策的法律框架提供了具体实例。",
