    "resourceId": "fr-2015-23245",
    "titleZh": "文件管理：通用文件调度表（GRS）传送单第25号——基于Capstone方法的电子邮件管理",
    "summaryShort": "本资料为美国国家档案与文件署（NARA）在《联邦公报》上发布的通知，介绍通用文件调度表（GRS）传送单第25号。它专门针对采用Capstone方法管理电子邮件的联邦机构，提供相应的文件处置授权。用户可以从中了解Capstone电子邮件管理相关的调度内容、使用方式以及被撤销的旧有调度项。",
    "summaryZh": "2015年9月16日，NARA通过《联邦公报》发布本通知，正式发布通用文件调度表（GRS）传送单第25号。该传送单为联邦机构在Capstone方法下管理的电子邮件提供了通用的文件处置授权。通知解释了传送单的具体内容、应用步骤，并说明此次仅发布新增或修订的调度项，而非重新发布所有已批准的GRS。同时，传送单撤销了此前与电子邮件管理相关的部分GRS项，以配合Capstone方法的全面实施。本资料文件了美国联邦政府电子文件管理，特别是高价值电子邮件鉴定与处置政策的一次重要制度化进展，为档案学领域研究数字文件管理策略、鉴定方法和国际比较提供了官方一手依据。",
    "keyPoints": [
      "该通知由美国国家档案与文件署（NARA）发布，具有联邦公报的正式法律效力，传送单于刊登之日生效。",
      "GRS Transmittal 25 专门针对采用Capstone方法管理联邦机构电子邮件的文件处置，提供新增的和修订的通用调度项。",
      "此次传送单未重刊所有此前批准的GRS，仅包含与Capstone电子邮件管理直接相关的变更，用户需将新调度与已有GRS结合使用。",
      "传送单同时明确了被撤销的旧有GRS项，以确保联邦机构在使用Capstone方法时不再依据过时的处置授权。",
      "通知详细说明了传送单的获取途径、使用指南以及相关查询联系方式，为联邦机构执行新调度提供了操作指引。"
    ],
    "researchValue": "本资料是研究美国联邦政府电子文件管理政策演变、特别是‘Capstone’电子邮件鉴定与处置方法的重要官方文献。研究者可将其用于：电子文件管理战略比较研究；通用文件调度表的制定与应用机制分析；电子邮件作为公共文件的长期保存与处置制度设计；以及中美档案法规与数字文件管理制度比较。对档案学学习者而言，它是理解境外数字文件处置授权和元管理实践的典型例证。",
