    "summaryZh": "本通知由 NARA 发布，正式公布了《通用文件日程表》（GRS）传送单第 24 号，自 2015 年 8 月 18 日起生效。GRS 为联邦机构提供共同的文件处置授权，涵盖人事、财务、行政等多类临时性文件。传送单第 24 号对既有 GRS 进行了修订，包括调整某些日程表编号和项目编号、更新布局并提供主题索引，以帮助机构更便捷地定位适用的处置项。同时，该传送单明确列举了被取代的 GRS 条款，要求各机构依新授权管理文件。此通知是 NARA 持续优化电子和物理文件管理框架的重要组成部分，为研究者提供了观察美国联邦文件处置政策演变的窗口。",
