    "titleZh": "公开会议通知：通用文件时间表（GRS）6.1“基于顶层方法的电子邮件管理”",
    "summaryShort": "这是美国国家档案与文件署（NARA）于2015年发布的联邦公报通知，宣布就通用文件时间表（GRS）6.1“基于顶层方法的电子邮件管理”举行公开会议。用户可以了解该时间表草案的讨论背景、会议参与方式及公众意见提交的具体要求。",
    "summaryZh": "该通知由美国国家档案与文件署（NARA）在联邦公报上发布，旨在就拟议的通用文件时间表（GRS）6.1——基于顶层方法（Capstone Approach）的电子邮件管理——征求公众意见，并宣布举行一场公开会议。GRS 6.1为联邦机构使用顶层方法管理电子邮件提供了处置授权，允许机构仅永久保存少数高级官员的电子邮件，而定期删除其他人员的邮件。通知中披露了会议时间（2015年5月21日）、参会报名截止日期（2015年5月18日）和书面意见提交截止日期（2015年6月1日），反映了美国联邦电子文件管理政策的制定过程与公众参与机制。对于研究电子文件管理政策、顶层电子邮件归档策略及档案开放决策的学者和从业者具有典型的参考价值。",
    "keyPoints": [
      "会议面向公众召开，专门讨论拟议的通用文件时间表（GRS）6.1，该时间表涉及通过“顶层方法”对联邦机构电子邮件进行处置。",
      "会议定于2015年5月21日（周四）上午10时至中午12时举行，拟参会者必须在2015年5月18日下午5时前回复报名。",
      "通知允许不参会者通过书面方式提交意见，书面意见须在2015年6月1日下班前通过电子邮件提交至NARA。",
      "该GRS 6.1旨在为使用Capstone方法管理电子邮件提供正式的文件处置授权，使机构能够以顶层官员邮件作为永久保存的档案核心。",
      "该通知由NARA发布，档案号NARA-2015-032，刊登于《联邦公报》80卷17511-17512页，是联邦文件管理规则制定过程中的公开征求意见环节。"
    ],
    "researchValue": "该资料可用于研究美国联邦机构电子邮件归档的“顶层模式”（Capstone Approach）政策，分析通用文件时间表的制定与公众评论流程，为电子文件管理政策比较、档案开放决策和电子文件处置制度研究提供具体案例。同时有助于理解NARA在数字资源保存与文件管理领域的规则制定实践及公共参与机制。",
