    "resourceId": "fr-2014-28697",
    "titleZh": "联邦资助机构实施管理和预算办公室统一行政要求、成本原则与审计要求的规则",
    "summaryShort": "这是2014年12月19日发布于《联邦公报》的最终规则，由包括国家档案馆在内的多家联邦机构联合发布，旨在将OMB的统一行政要求、成本原则与审计要求（2 CFR Part 200）落实为各机构的具体规章。用户可以从中了解联邦资助项目中电子文件管理、文件保存与审计合规的制度规范。",
    "summaryZh": "该规则由管理与预算办公室（OMB）及美国国家档案馆（NARA）等34个联邦机构联合发布，正式将《统一行政要求、成本原则与审计要求》（通常称为“超级通函”或2 CFR Part 200）纳入各联邦资助机构的部门规章。规则对联邦资助项目的行政程序、允许成本、间接成本率、审计标准等作出协调一致的规定。在档案学领域，该规则的收录价值主要体现为：NARA作为联邦资助机构之一，其资助活动（如国家历史出版物和档案资助）须遵守本规则，涉及受助者管理项目文件、保存财务和项目文件以及电子文件的法定要求，为研究美国联邦档案管理如何嵌入整体资助管理制度、以及电子文件在审计问责中的作用提供了重要法规依据。",
    "keyPoints": [
      "该规则由管理与预算办公室、国家档案馆、卫生部、国防部等34个联邦机构联合发布，将2 CFR Part 200的统一要求纳入各自部门的联邦资助管理规章。",
      "规则内容涵盖联邦资助的行政管理标准（如批准前费用、绩效监控）、成本原则（允许和不允许成本类型）以及审计要求（单一审计门槛和程序），为联邦拨款的管理提供一致框架。",
      "国家档案馆作为联邦资助机构之一，其受助人（如州和地方档案馆、历史出版机构等）须据此规则建立并维护项目档案和财务文件，包括以电子形式保存的文件，以满足审计和联邦检查要求。",
      "规则强调文件保存和访问权限，受助者必须按要求保管所有与拨款相关的文件，在审计或联邦审查时能够提供，这直接关联到机构电子文件管理政策和实践。",
      "该规则是OMB“超级通函”在各机构的实施规则，取代了此前分散在多个OMB通函（如A-21、A-87、A-110等）中的要求，体现了联邦资助管理从分散走向统一的改革。"
    ],
    "researchValue": "该资料可用于以下研究方向：一是档案制度比较研究，通过分析美国联邦资助文件管理要求，对比中国政府采购、科研资助等项目中的文件与档案管理规定；二是数字资源与电子文件治理研究，考察联邦如何通过统一审计和文件保存规则推动电子文件的合规管理，为电子文件长期保存和真实性保障提供政策参照；三是公共服务与档案资助体系研究，探究NARA如何将档案资助与其法定文件管理职责结合，在公开透明与问责框架下支持档案事业。",
    "resourceType": "law",
    "primaryTopicId": "electronic-records-management",
