    "titleZh": "机构信息收集活动：拟延长信息收集期限并征求公众意见",
    "summaryShort": "美国国家档案馆于2014年4月9日在《联邦公报》发布通知，就拟延长一项与电子文件管理相关的信息收集活动征求公众意见。用户可借此了解美国联邦档案机构在《文书工作削减法》框架下进行信息收集审查的程序与公众参与方式。",
    "summaryZh": "该通知由美国国家档案与文件署（NARA）发布，旨在依据《文书工作削减法》（Paperwork Reduction Act）的要求，就编号 NARA-2014-022 的信息收集活动延期提案公开征求意见。通知提供了信息收集的简要说明、估计的公众负担以及提交评论的截止日期（2014年6月9日），并指引公众通过联邦门户网站或邮寄方式提交意见。该资料属于电子文件管理领域的行政程序文件，展现了美国联邦档案机构在管控信息收集负担、确保行政透明与公众参与方面的操作实务。对于研究美国政府信息政策、档案行政程序以及电子文件管理法规环境的中国档案学学者和从业者，该通知可用于比较中外档案机构在信息收集审批与公众咨询机制上的制度差异，是理解美国档案系统行政合规性的重要原始材料。",
    "keyPoints": [
      "NARA依据《文书工作削减法》发布本通知，就一项与电子文件管理相关的信息收集活动的延期申请征求公众评论。",
      "通知中明确说明该信息收集活动的机构案卷号为NARA-2014-022，并要求公众在2014年6月9日前通过Regulations.gov网站或邮寄方式提交反馈。",
      "通知包含信息收集摘要、受影响的实体类型以及预估的年度报告负担小时数，体现了联邦机构在信息收集开始前必须进行的行政许可流程。",
      "该程序要求NARA在向管理和预算办公室（OMB）提交信息收集请求时，必须提供公众评论期，以确保收集的信息是必要的且不会造成不合理的负担。",
      "本通知作为《联邦公报》上的正式通告，展示了美国档案行政机构在电子文件管理活动中遵循的透明化与公众参与原则。"
    ],
    "researchValue": "该资料可用于：1）比较中美档案行政机构在信息收集审批流程、公众评论参与机制上的异同；2）研究美国《文书工作削减法》对联邦档案管理信息收集活动的约束作用；3）分析NARA在电子文件管理领域进行行政信息征集时的合规策略与信息披露方式；4）探讨档案系统用户负担评估和数据收集的公众审查制度。",
