    "resourceId": "fr-E7-19351",
    "titleZh": "《1974年隐私法》下文件系统通告的重新发布",
    "summaryShort": "美国国家档案与文件管理局（NARA）在《联邦公报》发布的通知，重新公布了其维护的37个文件系统通告，涵盖捐赠档案、实习生管理、文件培训等系统。用户可从中了解NARA文件系统的类别、目的、安全管理以及个人的查阅与修正权利。",
    "summaryZh": "2007年，NARA依据《1974年隐私法》(e)(4)条发布此通知，对其现有的37个文件系统进行重新公布并取代旧版通告。所涉系统包括藏品管理、志愿者和实习生计划、文件管理培训、保密协议等，每个系统均详细列出了系统名称、地点、覆盖的个人类别、文件内容、维护依据、使用目的、常规披露、存储与安保措施以及保留与处置时间表。该公告是执行隐私法透明性要求的关键步骤，确保公众知晓政府档案机构收集和维护个人信息的方式，同时也为研究者提供了剖析美国联邦档案机构个人信息管理体系的一手材料。",
    "keyPoints": [
      "NARA重新公布37个文件系统通告，系统涵盖文件管理培训参与者、捐赠档案协调、志愿者与实习生管理、信息系统安全协调等职能。",
      "每个系统通告均包含系统位置、文件类别、维护目的、常规使用以及个人查阅和修正文件的程序，如NARA 1系统为“文件管理培训参与者文件”。",
      "文件了各系统的物理和技术安全措施，如纸质文件保存在上锁文件柜，电子文件储存在光盘并设密码保护，限授权人员接触。",
      "规定了文件处置期限，例如部分系统在参与者完成项目后两年销毁，符合NARA的文件保存时间表。",
      "公报明确该重新发布旨在满足隐私法(e)(4)条的公开要求，并在生效日期前接受公众评论，如有实质意见将再发最终通告。"
    ],
    "researchValue": "该通知是美国档案机构依据《1974年隐私法》进行文件系统管理的原始实证材料，可用于档案学领域中的隐私保护制度比较研究、个人信息文件系统分类与管理模式分析、数字保存中的隐私合规策略探讨，以及公共服务中用户权利保障机制的研究。研究者可从中提取NARA在文件系统构建、安全控制和处置规则上的具体做法，为数字治理与档案法律交叉课题提供参考。",
