    "summaryShort": "美国国家档案馆（NARA）在《联邦公报》发布公告，就《国家档案馆数字化战略》草案公开征求意见。用户可了解该战略制定阶段的公众参与程序及数字化优先方向。",
    "summaryZh": "2014年10月16日，美国国家档案与文件署（NARA）通过《联邦公报》发布通知（档案号NARA-2015-003），就《国家档案馆数字化战略》草案征求公众意见，截止日期为当年11月17日。该战略旨在指导NARA大规模馆藏档案数字化，涉及优先事项、标准、合作伙伴关系及在线获取等议题。作为面向公众征求意见的官方文件，该通知体现了美国联邦档案机构在制定关键数字化政策时对透明度和公众参与的重视，为研究档案数字化政策形成过程、制度设计与公共服务参与机制提供了原始素材。",
