    "summaryShort": "这是美国国家档案与文件署（NARA）于1995年在《联邦公报》发布的拟议规则，旨在修订36 CFR第1228和1232部分，更新联邦机构视听文件的管理、保存与处置要求。用户可了解20世纪90年代美国联邦视听档案管理法规的制定背景与内容框架。",
    "summaryZh": "该资料为美国国家档案与文件署（NARA）于1995年9月28日发布的拟议规则（Proposed Rule），文件编号95-24024，公布于《联邦公报》（60 FR 50158）。该拟议规则旨在对《联邦法规》第36编（36 CFR）中第1228部分（联邦文件处置）和第1232部分（视听文件管理）进行修订，以完善联邦机构产生的视听文件（如照片、动态影像、录音等）的全生命周期管理规定。公众评论期于1995年11月27日截止。该文件反映了NARA在数字转型初期对视听材料归档、存储标准及处置程序进行系统规范的努力，是研究美国音像档案管理制度演进的重要原始法律文本，可用于国际档案法规比较、视听档案管理政策分析及电子文件管理历史研究。",
