    "researchValue": "该资料适用于档案学学习者和研究者了解美国联邦档案机构在1990年代数字档案检索系统建设的早期实践，尤其可用于研究数字档案保存战略、用户参与式评估机制、档案检索工具演进史以及公众服务改进策略。对比较不同国家档案信息定位系统的开发与评估模式也有参考意义。",
