    "resourceId": "fr-2016-05149",
    "titleZh": "尼克松政府总统历史材料（NARA最终规则）",
    "summaryShort": "该资料为美国国家档案馆（NARA）于2016年3月8日在联邦公报上发布的一项最终规则，修订了《联邦法规》第36篇第1275部分，专门针对尼克松政府总统历史材料的保存、保护与公众获取程序。用户可从中了解尼克松总统档案的特别管理法规、移交与开放条件。",
    "summaryZh": "本规则由美国国家档案馆（NARA）于2016年3月8日在联邦公报（81 FR 12007）发布，编号2016-05149，构成对36 CFR 1275的修订。该规则根据《总统录音与材料保存法》等法规，明确尼克松总统历史材料的法律定义、NARA的保管职责、材料的编目与保存标准，以及向公众开放的申请程序。规则对材料的移交、利用限制和公布条件作出具体规定，旨在平衡历史文档的长久保存与公众知情权。作为总统档案管理中的一个特殊案例，该规则对研究美国档案法制、总统图书馆制度以及敏感历史材料访问政策具有重要制度比较价值。",
    "keyPoints": [
      "由美国国家档案馆（NARA）发布，属于《联邦法规》第36篇第1275部分的修订，专门管理尼克松政府总统历史材料。",
      "规则依据《总统录音与材料保存法》（Presidential Recordings and Materials Preservation Act）制定，明确材料的保存、保护和获取程序。",
      "规定了材料的定义范围、移交NARA的条件、实体保存要求、编目处理及公众查阅申请的限制条款。",
      "规则于2016年4月7日生效，但若在2016年3月28日前收到反对意见，NARA将撤销本规则。",
      "本规则取消了之前的过渡期安排，统一了尼克松材料在NARA体系下的管理标准与开放政策。"
    ],
    "researchValue": "该资料对档案学研究者具有多重价值：可用于研究美国总统档案的特殊法律规制，尤其是尼克松政府历史材料因水门事件背景而受到的特别立法保护；可比较不同总统档案的获取政策差异，探讨公众知情权与个人隐私、国家安全的平衡机制；也适合作为档案法规制定的案例，分析NARA如何通过联邦公报规则细化立法要求。此外，该规则体现了总统图书馆体系在处理敏感政治档案时的制度设计，对各国档案敏感性材料管理具有参考意义。",
