    "resourceId": "fr-2011-492",
    "titleZh": "美国国家档案与文件署新机构标志规则",
    "summaryShort": "该资料为美国国家档案与文件署（NARA）于2011年发布的最终规则，修订了《联邦法规》第36篇第1200部分，正式引入并规定了NARA新机构标志（logo）的设计与使用要求。用户可从中了解美国联邦档案机构标志管理的法律依据及其修订程序。",
    "summaryZh": "本资料为美国国家档案与文件署（NARA）在《联邦公报》上发布的最终规则（Rule），文件编号2011-492。该规则修订了《联邦法规》第36篇第1200部分（36 CFR 1200），主要涉及官方印章和标志的管理。规则明确引入了NARA的新机构标志（logo），并通过对Subpart B（官方印章和标志的设计与使用）和Subpart C的修订，规定了新标志的法律地位、设计规范和使用限制。该规则于2011年1月11日生效，同时设有公开评论期，若收到不利评论将予撤回。该资料对于研究美国联邦档案机构的视觉识别制度、政府文件标志法规以及《联邦公报》的规则制定程序具有参考价值。",
    "keyPoints": [
      "该规则在36 CFR 1200的Subpart B（官方印章和标志的设计与使用）中增加了新的机构标志描述，并相应修改了Subpart C。",
      "规则由美国国家档案与文件署（NARA）发布，旨在为其引入并规范化新的机构标志（logo）。",
      "该最终规则规定于2011年1月11日立即生效，但若在2011年2月10日前收到不利评论，NARA将撤回该规则。",
      "公众可通过规定的渠道提交评论，行使参与联邦规则制定的权利。",
      "该规则确保了NARA新标志在官方文件、出版物及数字平台上的合法使用，强化了档案机构的视觉识别权威。"
    ],
    "researchValue": "该资料可用于档案学领域的机构品牌与视觉识别管理研究、美国政府文件标志的法律规制比较，以及《联邦公报》规则制定与公众参与流程分析。对于研究档案机构如何通过法规维护其官方标识的统一性和权威性，以及如何通过公众评论机制实现治理公开透明，具有案例价值。",
