      "修订36 CFR第1250部分“联邦文件的公众可用性与使用”，确保公众利用条款与新组织结构一致。",
      "修订36 CFR第1254部分“文件与捐赠历史材料的可用性”，进行了术语替换和错误的法规引用更正。",
      "本规则自2002年6月27日生效，属于无需事先公告和公众评论的技术性修订，依据5 U.S.C. 301等权限发布。"
