    "titleZh": "跨机构安全定密申诉小组（ISCAP）章程、规则与申诉程序",
    "summaryShort": "这是美国国家档案与文件管理局（NARA）发布的联邦法规，正式修订了跨机构安全定密申诉小组（ISCAP）的章程、规则和申诉程序。用户可以了解 ISCAP 的组织架构、表决机制及针对国家安全信息定密决定的申诉流程。",
    "summaryZh": "本资料为美国国家档案与文件管理局下设信息安全监督办公室（ISOO）于2012年7月9日在《联邦公报》上发布的最终规则，全文编入《联邦法规》第32卷第2003部分。它明确了跨机构安全定密申诉小组（ISCAP）的法律依据、成员构成、会议规则、表决程序和申诉审理机制。ISCAP的核心职能是审议并裁决由公众或机构就国家安全信息定密决定提出的申诉，其决定对各联邦机构具有约束力。该规则对书面申诉的提交要求、法定人数、投票门槛和决定公布程序作出具体规定，是美国档案解密与政府信息安全治理体系中一项关键的程序性规章，为研究信息开放、定密争议解决及跨机构监督机制提供了权威法律文本。",
    "keyPoints": [
      "该规则正式修订了《联邦法规》第32卷第2003部分，为ISCAP的运作提供了统一的法律框架。",
      "ISCAP由国防部、国务院、司法部、国家情报总监办公室、中央情报局及国家档案馆的高级代表组成，确保定密申诉审议的跨机构代表性。",
      "明确了申诉的书面提交格式、证据要求和提交时限，并规定了小组受理、驳回或要求补充材料的程序。",
      "规定小组会议须达到法定人数，决定由多数票通过，且主席有权在紧急情况下召集会议，确保决策效率。",
      "该规则于2012年9月7日生效，除非NARA在同年8月8日前收到足够的不利公众评论而被撤回。"
    ],
    "researchValue": "该资料适用于档案学、政治学及法学领域中关于政府信息开放、国家安全信息解密程序与跨机构治理的研究。可用于分析美国联邦机构安全定密的监督和申诉机制，比较不同国家档案解密申诉制度，探讨国家档案馆在定密争议解决中的角色，以及研究《信息自由法》（FOIA）框架下公众获取解密信息的法定路径。对于档案管理制度比较、数字资源开放政策分析和公共服务透明度研究具有重要参考意义。",
