    "resourceId": "fr-2012-4399",
    "titleZh": "通过引用纳入拟议规则",
    "summaryShort": "该资料是美国国家档案与文件署（NARA）联邦公报办公室于2012年发布的拟议规则，旨在修订《联邦法规》第1篇第51部分有关“通过引用纳入”的规定，以明确引用标准并保障公众获取所引用的材料。",
    "summaryZh": "该拟议规则由美国国家档案与文件署联邦公报办公室发布，文件号为NARA 12-0002，拟修订《联邦法规》第1篇第51部分中关于“通过引用纳入”的条款。该制度允许联邦机构在法规文本中引用已在其他地方发布的标准、手册等材料，而不必在《联邦公报》中全文翻印，从而简化流程、降低印制成本。拟议规则旨在进一步澄清可引用材料的类型、批准程序、引用材料的可用性与公开获取要求，以确保公众能够方便地查阅法规中引用的内容，强化透明度和公共问责。此规则与《信息自由法》所体现的公众知情权密切相关，对理解美国联邦法规制定中的文件公开与档案可获取性制度具有重要参考价值。",
    "keyPoints": [
      "由NARA联邦公报办公室提出，建议修订1 CFR Part 51中关于“通过引用纳入”的管理规则。",
      "明确联邦机构在法规中引用外部材料的批准标准、可引用材料的范围及引用格式要求。",
      "要求引用材料必须合理可用，并确保公众能够获取和查阅，以符合公开透明原则。",
      "拟议规则设有公众评论期（截至2012年3月28日），允许公众提交意见后形成最终规则。",
      "该规则与《联邦公报》发布流程及《信息自由法》下的公共查阅义务直接相关。"
    ],
    "researchValue": "该资料可用于研究美国联邦法规制定中的“通过引用纳入”制度，比较不同国家法规引用与文件公开机制，分析档案可获取性与政府透明度问题，以及探讨NARA在保障公众查阅政府发布材料方面的角色和制度设计。",
