    "researchValue": "该资料适用于档案开放利用与政府信息公开的跨国比较研究，特别是中美解密制度的法律基础对比；可用于研究国家安全信息保密与历史档案公共获取之间的制度平衡；同时为探究国家解密中心（NDC）的运作逻辑及其对数字档案资源建设的影响提供了法规实证。",
