    "titleZh": "1974年隐私法下的文件转移公告",
    "summaryShort": "该资料为美国国家档案与文件管理局（NARA）于1998年在《联邦公报》上发布的一项通知，根据1974年隐私法公开特定文件系统的转移信息，帮助用户了解联邦机构文件转移的合规流程与公众查阅权利。",
    "summaryZh": "这是一份由美国国家档案与文件管理局在《联邦公报》上发布的公告文件，依据1974年《隐私法》的规定，向公众通报NARA计划进行的若干文件系统的转移事项。该通知详细列明了所涉文件系统的名称、转移原因和法律依据，并说明了公众如何依据隐私法查阅相关文件或提出意见。作为联邦文件管理中的正式通知，它为档案学研究者提供了观察联邦机构在隐私保护框架下实施文件转移的具体案例，有助于理解档案开放利用与个人信息保护之间的制度安排。",
    "keyPoints": [
      "该公告由NARA发布，正式引用了1974年《隐私法》，标志着文件转移必须遵守的法定程序。",
      "通知中列出了一系列文件系统，说明这些文件将由一个机构单元转移至另一单元，或发生其他实质变动。",
      "公告向公众解释了文件转移对个人隐私的影响，并提供了查阅与反馈的渠道，确保个体知情权。",
      "文件刊登于1998年12月8日的《联邦公报》，占10页篇幅，具备官方法律效力。"
    ],
    "researchValue": "该资料可用于研究美国联邦机构在《隐私法》框架下的文件管理实践，特别是文件系统转移中涉及的隐私影响评估与公众告知义务。档案学学习者可借此分析档案利用与隐私保护的制度平衡，研究者可将其作为比较法研究或数字时代个人信息合规管理的参考案例，档案从业者则可了解NARA在实施文件监管时的操作流程。",
