    "summaryZh": "本文件为美国国家档案与文件署(NARA)下属信息安全监督办公室(ISOO)在《联邦公报》上发布的会议通知，涉及国家工业安全计划政策咨询委员会(NISPPAC)的一次公开会议。会议定于2019年3月13日上午10时至12时举行，面向公众开放，旨在讨论与工业安全政策相关的事项。该通知体现了联邦咨询委员会运作的公开透明原则，是研究美国工业安全政策公众参与渠道和美国联邦信息公开实践的直接资料，也反映了NARA在安全信息管理领域的协调角色。",
