    "resourceId": "fr-2021-03001",
    "titleZh": "自由信息法 (FOIA) 咨询委员会会议通知",
    "summaryShort": "这是一则由美国国家档案与文件署 (NARA) 发布于《联邦公报》的会议通知，公告了 2021 年 3 月 3 日举行的自由信息法咨询委员会会议及公众注册要求，用户可从中了解会议日程与参与方式。",
    "summaryZh": "该资料为美国国家档案与文件署 (NARA) 在《联邦公报》上发布的《自由信息法 (FOIA) 咨询委员会会议》通知（文件编号 2021-03001，86 FR 9541）。公告明确了委员会会议将于 2021 年 3 月 3 日上午 10 点至下午 1 点（东部时间）举行，并要求公众在 2 月 28 日前注册参与。该咨询委员会旨在就《自由信息法》的实施提供建议，是联邦政府推进开放信息和公众获取的重要机制。收录此通知有助于了解美国依照《联邦咨询委员会法》(FACA) 运作的 FOIA 咨询机制、公开会议程序及 NARA 在信息公开中的协调角色，为比较档案开放利用与咨询制度建设提供原始文献参考。",
    "keyPoints": [
      "会议定于 2021 年 3 月 3 日 10:00 – 13:00 (东部时间) 举行，公众出席截止注册时间为 2021 年 2 月 28 日 23:59 (东部时间)。",
      "发布机构为国家档案与文件署 (NARA)，文件登载于《联邦公报》第 86 卷第 9541-9542 页，文件编号 2021-03001，机构案卷号 NARA-2021-015。",
      "该通知为联邦咨询委员会会议公告，源自《联邦咨询委员会法》(FACA) 要求，旨在围绕《自由信息法》的行政管理、合规和程序问题搭建公众咨询与建言平台。",
      "页面显式声明此网站上的版本为“Web 2.0”原型版，并非官方法律版本，正式引用应以 govinfo.gov 上的官方 PDF 为准。"
    ],
    "researchValue": "该资料可用于档案开放利用与信息法研究，包括：美国《信息自由法》咨询委员会的运作模式、公众参与联邦咨询会议的程序设计、NARA 在政府信息公开中的协调职能，以及《联邦咨询委员会法》对咨询机构透明度的要求。中文档案学研究者可借此进行中美档案开放咨询制度比较，探讨将委员会听证、会议公示等机制引入国内档案公开监督体系的可能性。",
