    "resourceId": "fr-98-21023",
    "titleZh": "《通用文件保管期限表》修改通知及征求意见",
    "summaryShort": "这是美国国家档案与文件署（NARA）于1998年在《联邦公报》发布的一份通知，就拟议修改《通用文件保管期限表》公开征求意见。用户可从中了解美国联邦文件保管期限修订的程序、公众参与途径以及当时涉及电子文件管理的条款调整方向。",
    "summaryZh": "该资料为NARA在《联邦公报》（63 FR 41868）上发布的正式通知（文件号98-21023），宣布拟对《通用文件保管期限表》（GRS）进行修改，并邀请公众在1998年9月4日前提交意见。通知共5页，列出了具体拟修改的条目，体现了NARA依据《美国法典》授权对联邦文件处置进行监管的职责。作为20世纪末美国电子文件管理政策演进中的原始程序文档，该通知为档案学研究者提供了文件保管期限表修订过程的实例，展示了法规制定中的公众评议机制，并可服务于电子文件保管政策变迁、中外文件处置制度比较以及档案立法程序等专题研究。",
    "keyPoints": [
      "NARA行使联邦文件管理法定职权，拟对《通用文件保管期限表》的部分条目进行修改，具体修改内容详见通知正文及附表。",
      "公开征求意见期为30天，截止日期为1998年9月4日，反映了美国联邦文件保管期限修订中的公众参与和透明化程序。",
      "该通知发布于《联邦公报》，具有官方性质，是研究美国文件保管期限表修订机制的原始程序文件。",
      "拟议修改涉及多种文件类型，包括电子文件相关条目，为观察20世纪末电子文件保管政策的具体调整提供实证。"
    ],
    "researchValue": "该资料适用于美国电子文件管理政策演变、联邦文件保管期限制度、档案立法中的公众参与机制以及中外文件处置规程比较等档案学研究课题。它也为探究NARA监管职能的历史实践和通用文件保管期限表的版本沿革提供了第一手证据。",
