    "resourceId": "fr-2026-13590",
    "titleZh": "美国州、地方、部落和私营部门政策咨询委员会(SLTPS-PAC)会议通知",
    "summaryShort": "本资料为美国国家档案与文件署（NARA）在联邦公报上发布的会议通知，宣布SLTPS-PAC将于2026年7月22日举行虚拟会议，并说明公众参与方式。用户可了解该咨询委员会的公开会议安排与联络信息。",
    "summaryZh": "本文件是美国国家档案与文件署（NARA）于2026年7月6日在联邦公报上发布的一则会议通知，涉及州、地方、部落和私营部门政策咨询委员会（SLTPS-PAC）的公开会议。会议定于2026年7月22日上午11:30至中午12:30通过网络虚拟方式举行。通知向公众提供了参与途径，要求有意参加者提前联系指定负责人Kimberly Andersen。该委员会负责就国家安全信息访问、保护及相关政策向总统和管理和预算办公室提供建议，是公众参与档案与信息安全政策讨论的重要渠道。作为联邦公报中的正式通告，本资料是研究美国档案与信息安全领域公共参与机制、咨询委员会运作模式的原始法律文件。",
    "keyPoints": [
      "发布机构为美国国家档案与文件署（NARA），文件编号为2026-13590，发布在联邦公报91卷41086页。",
      "SLTPS-PAC会议时间为2026年7月22日上午11:30至12:30（美国东部时间），以虚拟形式举行。",
      "公众可通过联系Kimberly Andersen（电话：301-837-3744，邮箱：kimberly.andersen@nara.gov）申请虚拟参会。",
      "该委员会负责就涉及州、地方、部落和私营部门的国家安全信息访问及保护政策问题向总统和管理和预算办公室提供建议。",
      "此通知为联邦公报上的正式公告，告知公众委员会会议信息和参与方式，是公众参与美国联邦档案政策讨论的官方渠道之一。"
    ],
    "researchValue": "本资料可作为研究美国档案与文件领域公共参与制度和咨询委员会机制的原始法律文件。中文档案学研究者可通过该会议通知，考察美国国家档案与文件署在公共政策制定中的开放性与透明度，了解其如何通过联邦公报发布会议信息来保障公众知情权和参与权。此外，它还可用作比较中外档案行政机构咨询机制、公众听证会制度的典型案例，对于数字档案事业的公共治理、档案公共服务和法规遵从研究具有参考价值。",
