    "resourceId": "fr-2017-19721",
    "titleZh": "国家工业安全计划政策咨询委员会2017年11月会议公告",
    "summaryShort": "这是美国国家档案与文件管理局（NARA）信息安全监督办公室于2017年9月18日在《联邦公报》上发布的会议通知，宣布国家工业安全计划政策咨询委员会（NISPPAC）将于2017年11月1日举行公开会议，用户可从中了解会议时间、地点、开放方式及参与要求。",
    "summaryZh": "该资料为美国《联邦公报》刊载的正式会议通知，由美国国家档案与文件管理局下属信息安全监督办公室发布。通知宣布国家工业安全计划政策咨询委员会（NISPPAC）将在2017年11月1日于华盛顿特区国家档案馆大楼召开公开会议，会议时间为上午10:00至中午12:00。该咨询委员会负责就工业安全计划政策向政府提供建议，本次会议向公众开放，但因安全要求，出席人员需提前提交姓名以核验身份。该通知对于研究美国政府档案与安全管理机构如何通过咨询委员会机制实现公众参与具有政策参考价值，同时反映了NARA在工业安全政策协调中的角色。",
    "keyPoints": [
      "发布机构为美国国家档案与文件管理局（NARA）下属的信息安全监督办公室（ISOO），通知编号为NARA-2017-065。",
      "会议时间为2017年11月1日上午10:00至中午12:00（东部标准时间），地点为华盛顿特区宾夕法尼亚大道700号国家档案馆大楼。",
      "会议对公众开放，但出于安全考虑，所有参会的公众人员必须提前提交姓名，以供核实身份。",
      "会议将讨论国家工业安全计划政策事项，最终议程将在NARA官方网站公布，联系人指定为Katelyn E. Gorski。",
      "该通知作为联邦公报文件，具有正式法律告知作用，但该网站版本仅为原型，最终官方版本应以GPO govinfo.gov为准。"
    ],
    "researchValue": "该资料适用于以下档案学研究领域：美国政府档案管理机构（NARA）在工业安全管理中的协调职能研究；联邦咨询委员会机制在档案与安全政策制定中的公众参与模式分析；政府文件开放性与安全审查之间的平衡实践考察；以及基于联邦公报通知的政策过程透明度研究。对中国档案学学习者和从业者而言，可将其作为比较中外档案行政监管、政策咨询和公众参与制度的参考案例。",
