    "summaryShort": "这是美国国家档案与文件署（NARA）下属信息安全监督办公室（ISOO）于2015年12月15日在《联邦公报》上发布的一则会议通知。该通知宣布了州、地方、部落和私营部门政策咨询委员会（SLTPS-PAC）将于2016年1月27日召开会议。用户可从中了解美国联邦政府档案与信息安全政策制定过程中的公众参与机制，以及相关咨询委员会的运作信息。",
    "summaryZh": "本资料是美国《联邦公报》上发布的一则官方通知，由美国国家档案与文件署（NARA）下属的信息安全监督办公室（ISOO）发布。通知正式宣布了州、地方、部落和私营部门政策咨询委员会（SLTPS-PAC）将于2016年1月27日举行会议。该委员会是NARA在制定和实施涉及州、地方、部落政府及私营部门的档案与信息安全政策时的重要咨询机构。此通知是研究美国档案治理中多元主体参与、政策咨询机制以及《联邦公报》作为政府信息公开与公众参与平台运作的典型案例。资料本身为《联邦公报》的网页版展示，并明确标注其非官方法律版本的性质，提醒研究者引用时需核对官方PDF版本。",
