    "summaryShort": "这是美国国家档案与文件署（NARA）于2018年9月14日在《联邦公报》上发布的一则公告。该公告通知公众，总统图书馆-基金会合作伙伴关系咨询委员会将于2018年9月26日召开会议。用户可以从中了解该咨询委员会会议的召开时间、地点等基本信息。",
    "summaryZh": "本资料是美国国家档案与文件署（NARA）于2018年9月14日在《联邦公报》上发布的官方公告。该公告旨在通知公众，根据《联邦咨询委员会法》，总统图书馆-基金会合作伙伴关系咨询委员会将于2018年9月26日上午9点至12点在马里兰州大学公园市的国家档案馆大楼召开会议。公告提供了会议时间、地点等基本信息，并说明了会议对公众开放的性质。该资料是了解美国联邦政府档案管理机构如何通过法定咨询委员会机制，就总统图书馆与相关基金会合作等特定议题进行公开咨询和治理的实例。",
