    "summaryShort": "这是一份由美国国家档案与文件管理局（NARA）于2012年2月23日发布的《联邦公报》通知。该通知宣布将于2012年3月27日举行一次公开会议，旨在就奥巴马总统2011年11月签署的《管理政府档案》备忘录（Managing Government Records）的实施征求公众意见。用户可以从中了解美国联邦政府推动电子文件管理改革的早期公众参与机制。",
    "summaryZh": "本资料是美国国家档案与文件管理局（NARA）在《联邦公报》上发布的一份官方通知。该通知宣布，为响应奥巴马总统于2011年11月签署的《管理政府档案》备忘录，NARA将于2012年3月27日召开一次公开会议，向公众、利益相关方和机构代表征集关于如何有效实施该备忘录、改进政府文件管理（特别是向电子文件管理过渡）的意见和建议。这份文件反映了美国联邦政府在推动全面的政府文件管理现代化改革过程中的一个关键公众参与环节，体现了政策制定过程中的透明度和协商机制。",
