    "resourceId": "fr-2010-17997",
    "titleZh": "关于总统图书馆-基金会合作伙伴关系咨询委员会的公告",
    "summaryShort": "这是美国国家档案与文件署（NARA）于2010年7月22日在《联邦公报》上发布的一份公告。该公告宣布成立“总统图书馆-基金会合作伙伴关系咨询委员会”。用户可从中了解该咨询委员会的成立背景、目的及其在总统图书馆管理体系中的角色。",
    "summaryZh": "本资料是美国国家档案与文件署（NARA）于2010年7月22日在《联邦公报》上发布的一份公告，文件编号为2010-17997。该公告正式宣布成立“总统图书馆-基金会合作伙伴关系咨询委员会”。该委员会的设立旨在就总统图书馆与相关私人基金会之间的合作、管理及资金等问题，向国家档案与文件署署长提供咨询和建议。这份公告是理解美国联邦政府如何通过设立专门咨询机构来协调官方档案机构与私人基金会关系、优化总统图书馆治理结构的重要政策文件。它体现了美国在总统档案管理领域，对公私合作模式的制度化探索。",
    "keyPoints": [
      "公告由美国国家档案与文件署（NARA）发布，正式宣布成立“总统图书馆-基金会合作伙伴关系咨询委员会”。",
      "该咨询委员会的核心职能是就总统图书馆与私人基金会之间的合作伙伴关系向NARA署长提供建议。",
      "该委员会的设立旨在应对总统图书馆管理中涉及的公共机构与私人基金会之间的协调、治理及资金筹措等复杂问题。",
      "此公告是《联邦公报》上的一份正式通知（Notice），属于联邦政府行政程序的一部分。",
      "文件明确指出，该网站版本为原型版本，不具有正式法律效力，正式版本需参考govinfo.gov上的官方PDF文件。"
    ],
    "researchValue": "该资料为研究美国档案治理，特别是总统档案管理制度提供了关键的政策依据。可用于研究美国联邦政府如何通过设立咨询委员会来协调公共档案机构与私人基金会的关系，分析公私合作（PPP）模式在国家级档案机构（如总统图书馆）运营管理中的应用与挑战。对于比较档案学、档案政策与法律、档案机构治理以及总统档案管理等领域的研究者和从业者具有重要参考价值。",
